struct vector3d {
    float x;
    float y;
    float z;
};

struct sphere {
    vector3d center;
    float radius;

    sphere(const vector3d &value, float size) : center(value), radius(size) {}
};

class ai_polypath_cell;
class region {
public:
    void add(ai_polypath_cell *cell);
};

struct region_node {
    void *key;
    region *value;
};

struct sector {
    region_node *node;
};

class terrain {
public:
    sector *find_sector(const vector3d &position) const;
};

template<class T> class vector {
public:
    T *begin_value;
    T *end_value;
    T *capacity_value;

    void resize(unsigned size);
    T *begin() { return begin_value; }
    T *end() { return end_value; }
};

extern vector<region_node *> cell_regions;
extern int warning(const char *format, ...);

class ai_polypath_cell {
    char padding0[64];
    vector3d m_CenterPoint;
    float radius;
    char padding1[164];
    char sector_valid;

public:
    void compute_sector(terrain &ter, bool use_high_res_intersect);
    void _intersect(
        region_node *node,
        const sphere &the_sphere,
        bool use_high_res_intersect
    );
};

void ai_polypath_cell::compute_sector(
    terrain &ter,
    bool use_high_res_intersect)
{
    sector_valid = false;
    sector *center_sector = ter.find_sector(m_CenterPoint);
    if (center_sector)
    {
        cell_regions.resize(0);
        sphere cell_sphere(m_CenterPoint, radius);
        _intersect(center_sector->node, cell_sphere, use_high_res_intersect);
        region_node **current = cell_regions.begin();
        region_node **finish = cell_regions.end();
        for (; current != finish; ++current)
            (*current)->value->add(this);
        sector_valid = true;
    }
    else
    {
        sector *vertex_sector[3];
        for (int i = 0; i < 3; ++i)
            vertex_sector[i] = ter.find_sector(
                *reinterpret_cast<vector3d *>(
                    reinterpret_cast<char *>(this) + 28 + i * 12));

        if (
            vertex_sector[0]
            && vertex_sector[1]
            && vertex_sector[2]
            && vertex_sector[0]->node == vertex_sector[1]->node
            && vertex_sector[0]->node == vertex_sector[2]->node)
        {
            vertex_sector[0]->node->value->add(this);
            sector_valid = -1;
        }
    }

    if (!sector_valid)
        warning(
            "A polypath triangle is outside the world and cannot be auto-fixed! "
            "(center <%.2f, %.2f, %.2f>), please check and re-export!!",
            m_CenterPoint.x,
            m_CenterPoint.y,
            m_CenterPoint.z);
}
